FOLDER_ORDER = {k: i for i, k in enumerate(FOLDERS)}


def folder_rank(key):
    """Folders are shown in the order FOLDERS lists them, under their role."""
    parts = key.split(' / ')
    return (ROLE_ORDER.index(parts[0]), FOLDER_ORDER.get(key, 10_000), key)
